--Q1.Total Revenue generated by male vs Female customers?
select gender,sum(purchase_amount) as revenue from customer group by gender;

--Q2.Which Customers used a discount but still spent more than the average purchase amount?
select customer_id,purchase_amount from customer where discount_applied = 'Yes' and purchase_amount > (select avg(purchase_amount) from customer);

--Q3.Which are the top 5 average products with highest average review rating?
select * from customer;
select item_purchased,round(cast(avg(review_rating)as numeric),2) as "Average product rating"
from customer group by item_purchased order by avg(review_rating) desc ; 

--Q4.Compare the average purchase amount between standard shipping and express shipping?
select shipping_type,round(avg(purchase_amount),2) from customer where shipping_type in ('Standard','Express') group by shipping_type;

--Q5.Do Subscribed Customer spend more?Compare to average spend and total revenue 
--between subscribers and non-subscribers.
select subscription_status,count(customer_id) as "Total Customer",round(avg(purchase_amount),2) as "average_spend",
round(sum(purchase_amount),2)as "total_revenue" from customer group by subscription_status order by "total_revenue","average_spend" desc;

--Q6.Which 5 products have highest percentage of purchases with discount applied?
select item_purchased,round(100*sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer 
group by item_purchased
order by discount_rate desc;

--Q7.Segment Customer into new, Returning, and loyal based on their total 
--number of previous purchases, and shows the count of each segment.
--With CTE Statement Common Tool Expression, it is a virtual table for query use.
with customer_type as(
select customer_id, previous_purchases,
case
	when previous_purchases=1 then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
	else 'Loyal'
	end as customer_segment
from customer
)
select customer_segment ,count(*) as "Number of Customers"
from customer_type
group by customer_segment;

--Q8.What are the top 3 most purchased products withinn each category
with item_counts as(
select category,
item_purchased,
count(customer_id)as Total_Orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customer 
group by category, item_purchased
)

select item_rank,category,item_purchased,Total_Orders 
from item_counts
where item_rank<=3;

--Q9.Are Customers who are repeat buyers(more than 5 previous purchases)also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from customer
where previous_purchases>5
group by subscription_status;

--Q10.What is revenue contribution of each group?
select * from customer;
select age_group,
sum(purchase_amount)as"Total_Revenue"
from customer 
group by age_group
order by "Total_Revenue" desc;